  .filterBounds(aoi).filterDate('2023-01-01', '2024-01-01')
  .sort('CLOUD_COVER').first();
var sr = l9.select('SR_B.*').multiply(0.0000275).add(-0.2);
Map.addLayer(sr, {bands: ['SR_B4', 'SR_B3', 'SR_B2'], min: 0, max: 0.25}, 'Landsat 9 true colour');
```
Compared with Sentinel-2 at 10 m, Landsat at 30 m looks softer: narrow channels, roads and fringes blur, but the colours should match closely once both are in reflectance (0-0.25 stretch). If Landsat looks washed out, the offset was skipped.

